def searchMatrix(self, m: list[list[int]], target: int) -> bool:
    if not m or not m[0]:
        return False
    i, j = 0, len(m[0]) - 1
    while i < len(m) and j >= 0:
        if m[i][j] == target:
            return True
        if m[i][j] > target:
            j -= 1
        else:
            i += 1
    return False

